"use client"

import * as React from "react"
import { Input as InputPrimitive } from "@base-ui/react/input"
import { cva, type VariantProps } from "class-variance-authority"
import { Icon } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"
import { InputGroup, InputGroupAddon } from "./input-group"
import { Tooltip, TooltipContent } from "./tooltip"

const inputVariants = cva(
  "w-full min-w-0 rounded-md border border-input bg-card text-sm transition-colors duration-fast ease-entrance outline-none file:inline-flex file:h-6 file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground hover:border-text-muted focus-ring [&[readonly]]:bg-bg-subtle disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-40 aria-invalid:border-error aria-invalid:focus-ring-error",
  {
    variants: {
      size: {
        // Field heights are density tokens (styles.css): compact 32/36/40 — the
        // Button sm/md/lg — and data-density="comfortable" 36/44/52.
        sm: "h-(--field-sm) px-3 text-[13px]/[18px]",
        default: "h-(--field-md) px-3",
        lg: "h-(--field-lg) px-3",
      },
    },
    defaultVariants: {
      size: "default",
    },
  }
)

type InputControlProps = Omit<React.ComponentProps<"input">, "size"> & VariantProps<typeof inputVariants>

/**
 * The bare control: the `<input>` and its validation tooltip. Constraint
 * validation (`required`, `type="email"`, `pattern`, `minLength`…) answers in
 * the WunderUI tooltip instead of the browser's own bubble: on submit the first
 * invalid field is focused and shows the browser's message in a Tooltip, and
 * the message clears as soon as the user types or leaves the field.
 */
function InputControl({
  className,
  type,
  size = "default",
  ref,
  onInvalid,
  onInput,
  onBlur,
  ...props
}: InputControlProps) {
  const inputRef = React.useRef<HTMLInputElement | null>(null)
  const [message, setMessage] = React.useState<string | null>(null)
  const shown = React.useRef("")
  if (message) shown.current = message

  const setRefs = React.useCallback(
    (node: HTMLInputElement | null) => {
      inputRef.current = node
      if (typeof ref === "function") ref(node)
      else if (ref) (ref as React.RefObject<HTMLInputElement | null>).current = node
    },
    [ref]
  )

  return (
    <>
      <InputPrimitive
        ref={setRefs}
        type={type}
        data-slot="input"
        className={cn(inputVariants({ size }), className)}
        onInvalid={(event: React.FormEvent<HTMLInputElement>) => {
          onInvalid?.(event)
          if (event.defaultPrevented) return
          event.preventDefault()
          const input = event.currentTarget
          // Every invalid field fires; only the first one in the form speaks.
          // Controls only: a <fieldset> around an invalid field matches :invalid too
          // and comes first in document order, which would silence every field in it.
          const first = input.form?.querySelector<HTMLElement>(":is(input, select, textarea):invalid")
          if (first && first !== input) return
          input.focus()
          setMessage(input.validationMessage)
        }}
        onInput={(event: React.InputEvent<HTMLInputElement>) => {
          onInput?.(event)
          if (message) setMessage(null)
        }}
        onBlur={(event: React.FocusEvent<HTMLInputElement>) => {
          onBlur?.(event)
          if (message) setMessage(null)
        }}
        {...props}
        aria-invalid={message ? true : props["aria-invalid"]}
      />
      <Tooltip open={!!message}>
        <TooltipContent anchor={inputRef} side="bottom" align="start" role="alert">
          {shown.current}
        </TooltipContent>
      </Tooltip>
    </>
  )
}

type InputFieldProps = {
  /** Visible label. Joined to the control with `htmlFor`. */
  label?: React.ReactNode
  /** A tag or a link on the label row, right-aligned (for example "Forgot password?"). */
  labelTrailing?: React.ReactNode
  /** Adds the "(optional)" tag to the label. */
  optional?: boolean
  /** Hint below the field. Replaced by `error` while there is one. */
  helper?: React.ReactNode
  /** Error message below the field. Sets `aria-invalid` and `aria-describedby`. */
  error?: React.ReactNode
  /** Content inside the field, before the text (icon, prefix). */
  leading?: React.ReactNode
  /** Content inside the field, after the text (icon, suffix, button). */
  trailing?: React.ReactNode
  /** Class names for the wrapper around label, field and message. */
  wrapperClassName?: string
  /** With `type="password"`: adds the button that shows or hides what was typed. */
  revealable?: boolean
}

type InputProps = InputControlProps & InputFieldProps

/** The props that turn the bare control into a field. Presence of the prop counts, not its value, so a
 *  conditional `error={cond ? "…" : undefined}` never swaps the DOM (and drops the focus) when it flips. */
const FIELD_PROPS = ["label", "labelTrailing", "optional", "helper", "error", "leading", "trailing", "wrapperClassName", "revealable"] as const

/**
 * Text input. Constraint validation (`required`, `type="email"`, `pattern`,
 * `minLength`…) answers in the WunderUI tooltip instead of the browser's own
 * bubble: on submit the first invalid field is focused and shows the browser's
 * message in a Tooltip, and the message clears as soon as the user types or
 * leaves the field.
 *
 * Without any of the field props (`label`, `labelTrailing`, `optional`, `helper`,
 * `error`, `leading`, `trailing`, `wrapperClassName`, `revealable`) it renders
 * the bare `<input>`. With one of them it renders the field: label row, the
 * control (inside an Input Group when there is leading or trailing content),
 * and the helper or error line, wired with `htmlFor`, `aria-invalid` and
 * `aria-describedby`. `revealable` on `type="password"` adds the show/hide button.
 */
function Input(props: InputProps) {
  const autoId = React.useId()
  const [visible, setVisible] = React.useState(false)
  if (!FIELD_PROPS.some((key) => key in props)) return <InputControl {...props} />

  const { label, labelTrailing, optional, helper, error, leading, trailing, wrapperClassName, revealable, size, id: idProp, className, ...rest } = props
  const id = idProp ?? autoId
  const reveal = !!revealable && rest.type === "password"
  const describedBy = error ? `${id}-error` : helper ? `${id}-helper` : undefined
  // A disabled field dims its label and helper line with the control (Figma Field / Disabled).
  const dim = rest.disabled ? "opacity-40" : undefined
  const end = reveal ? (
    <>
      {trailing}
      <button
        type="button"
        onClick={() => setVisible((v) => !v)}
        aria-label={visible ? "Hide password" : "Show password"}
        aria-pressed={visible}
        className="rounded-sm text-text-tertiary outline-none hover:text-foreground focus-ring"
      >
        {/* The icon shows the current state: dots hidden behind a
            crossed-out eye, plain text behind an open one. */}
        {visible ? <Icon name="show" className="size-4" /> : <Icon name="hide" className="size-4" />}
      </button>
    </>
  ) : (
    trailing
  )
  const control = (
    <InputControl
      id={id}
      size={size}
      aria-invalid={error ? true : undefined}
      aria-describedby={describedBy}
      className={className}
      {...rest}
      type={reveal && visible ? "text" : rest.type}
    />
  )
  return (
    <div data-slot="input-field" className={cn("flex flex-col gap-1", wrapperClassName)}>
      {(label || labelTrailing) && (
        <div className="mb-1 flex items-center justify-between gap-2">
          {label && (
            <label htmlFor={id} className={cn("text-sm font-medium text-foreground", dim)}>
              {label}
              {optional && <span className="ms-1 font-normal text-text-tertiary">(optional)</span>}
            </label>
          )}
          {labelTrailing}
        </div>
      )}
      {leading || end ? (
        <InputGroup className={cn(size === "sm" && "[--ig-h:var(--field-sm)]", size === "lg" && "[--ig-h:var(--field-lg)]", error && "border-destructive")}>
          {leading && <InputGroupAddon>{leading}</InputGroupAddon>}
          {control}
          {end && <InputGroupAddon>{end}</InputGroupAddon>}
        </InputGroup>
      ) : (
        control
      )}
      {error ? (
        <p id={`${id}-error`} className="text-xs text-text-error">
          {error}
        </p>
      ) : (
        helper && (
          <p id={`${id}-helper`} className={cn("text-xs text-text-tertiary", dim)}>
            {helper}
          </p>
        )
      )}
    </div>
  )
}

export { Input, inputVariants }
export type { InputProps, InputFieldProps }

"use client"

import * as React from "react"
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip"
import { cn } from "@/lib/utils"

const TooltipContext = React.createContext<{ id: string; open: boolean } | null>(null)

/**
 * Shared delay for a group of tooltips, for example a toolbar: the first tooltip opens after
 * `delay` ms, and moving to the next trigger within `timeout` ms shows its tooltip at once.
 */
function TooltipProvider({ delay = 600, closeDelay = 0, timeout = 300, ...props }: TooltipPrimitive.Provider.Props) {
  return (
    <TooltipPrimitive.Provider delay={delay} closeDelay={closeDelay} timeout={timeout} {...props} />
  )
}

function Tooltip({ defaultOpen, open, onOpenChange, ...props }: TooltipPrimitive.Root.Props) {
  const id = React.useId()
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen ?? false)
  const isOpen = open ?? uncontrolledOpen
  const contextValue = React.useMemo(() => ({ id, open: isOpen }), [id, isOpen])

  return (
    <TooltipContext.Provider value={contextValue}>
      <TooltipPrimitive.Root
        data-slot="tooltip"
        defaultOpen={defaultOpen}
        open={open}
        {...props}
        onOpenChange={(nextOpen, eventDetails) => {
          setUncontrolledOpen(nextOpen)
          onOpenChange?.(nextOpen, eventDetails)
        }}
      />
    </TooltipContext.Provider>
  )
}

function TooltipTrigger({ describe = true, "aria-describedby": ariaDescribedBy, ...props }: TooltipPrimitive.Trigger.Props & { describe?: boolean }) {
  const context = React.useContext(TooltipContext)
  const describedBy = context && describe !== false && context.open
    ? [ariaDescribedBy, context.id].filter(Boolean).join(" ")
    : ariaDescribedBy

  return (
    <TooltipPrimitive.Trigger
      data-slot="tooltip-trigger"
      {...props}
      aria-describedby={describedBy}
    />
  )
}

function TooltipContent({
  className,
  sideOffset = 8,
  children,
  side = "top",
  align,
  anchor,
  shortcut,
  linger = false,
  arrow = true,
  maxWidth = 240,
  ...props
}: TooltipPrimitive.Popup.Props &
  Pick<TooltipPrimitive.Positioner.Props, "sideOffset" | "side" | "align" | "anchor"> & {
    /** Keyboard hint rendered after the label, e.g. "⌘K" (Figma Type=shortcut). */
    shortcut?: string
    /**
     * For confirmations such as "Copied to clipboard": appears at once and,
     * when closed, drifts up slightly while it fades out slowly instead of
     * snapping away.
     */
    linger?: boolean
    /** Show the small point towards the trigger (Figma Show arrow). */
    arrow?: boolean
    /** Widest the label grows before the text wraps onto the next line: 240 px, or 320 px for long translations. */
    maxWidth?: 240 | 320
  }) {
  const context = React.useContext(TooltipContext)
  const maxWidthClass = {
    240: "max-w-60",
    320: "max-w-80",
  } as const

  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Positioner className="isolate z-50 outline-none" sideOffset={sideOffset} side={side} align={align} anchor={anchor}>
        <TooltipPrimitive.Popup
          data-slot="tooltip-content"
          id={context?.id}
          role="tooltip"
          className={cn(
            // fill-mode-both: the popup is invisible during the enter delay and stays
            // invisible after the exit — without it, it flashes at full opacity at both ends.
            "z-50 inline-flex items-center rounded-md bg-neutral-dark-content px-4 py-2 has-[kbd]:py-[7px] text-xs font-medium text-neutral-white shadow-md fill-mode-both data-open:animate-in data-open:data-instant:animate-none data-closed:data-instant:animate-none data-open:fade-in-0 origin-(--transform-origin) data-open:zoom-in-98 data-open:duration-fast data-open:delay-instant data-open:ease-entrance data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-98 data-closed:duration-instant data-closed:ease-exit",
            maxWidthClass[maxWidth],
            linger &&
              "data-open:delay-0 data-open:slide-in-from-bottom-1 data-closed:zoom-out-100 data-closed:slide-out-to-top-1 data-closed:duration-ambient data-closed:ease-move",
            className
          )}
          {...props}
        >
          {children}
          {shortcut && (
            <kbd className="ms-2 inline-flex h-[18px] items-center rounded-sm bg-bg-tooltip-key px-[5px] font-sans text-xs leading-4 font-semibold text-neutral-white shrink-0 whitespace-nowrap">
              {shortcut}
            </kbd>
          )}
          {/* The arrow points down by default (tooltip above the trigger); when the
              tooltip flips or sits beside the trigger it turns to keep pointing at it. */}
          {arrow && (
            <TooltipPrimitive.Arrow className="data-[side=bottom]:top-[-4px] data-[side=bottom]:rotate-180 data-[side=left]:right-[-6px] data-[side=left]:-rotate-90 data-[side=right]:left-[-6px] data-[side=right]:rotate-90 data-[side=top]:bottom-[-4px]">
              <svg width="10" height="5" viewBox="0 0 10 5" fill="none">
                <path d="M0 0L5 5L10 0Z" className="fill-neutral-dark-content" />
              </svg>
            </TooltipPrimitive.Arrow>
          )}
        </TooltipPrimitive.Popup>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  )
}

export { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

"use client"

import * as React from "react"
import { Icon } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"
import { Button } from "./button"

/** Wraps an Input plus leading/trailing addons (icons, buttons) in one
 *  bordered field — the outer border/focus ring lives here, not on the
 *  inner <input>, so addons sit flush inside it. */
function InputGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="input-group"
      // Equal inner spacing (owner 15 Nov 2026): a key cap or a button at the end sits as far from the right edge as from
      // the top and bottom, (field height - 2 px border - item height) / 2. A button is shrunk to a 4 px gap all round.
      className={cn(
        "flex h-(--ig-h) [--ig-h:var(--field-md)] w-full items-center gap-2 rounded-md border border-input bg-card px-3 text-sm transition-colors duration-fast ease-entrance has-[[data-slot=input-group-addon]:last-child_kbd]:pe-[calc((var(--ig-h)-2px-22px)/2)] has-[[data-slot=input-group-addon]:last-child>[data-slot=button]]:pe-1 has-disabled:pointer-events-none has-disabled:opacity-40 has-[input[readonly]]:bg-bg-subtle hover:border-text-muted focus-ring-within has-[input[aria-invalid=true]]:border-error has-[input[aria-invalid=true]]:focus-ring-within-error [&>input]:h-full [&>input]:flex-1 [&>input]:rounded-none [&>input]:border-none [&>input]:bg-transparent [&>input]:p-0 [&>input]:text-sm [&>input]:shadow-none [&>input]:outline-none [&>input]:focus-visible:outline-none [&>input]:focus-visible:ring-0 [&>input]:aria-invalid:ring-0 dark:[&>input]:bg-transparent [&>input[readonly]]:bg-transparent",
        className
      )}
      {...props}
    />
  )
}

function InputGroupAddon({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="input-group-addon"
      className={cn(
        "flex shrink-0 items-center text-text-tertiary [&_svg]:pointer-events-none [&_svg]:size-4 [&>[data-slot=button]]:h-[calc(var(--ig-h)-2px-0.5rem)] [&>[data-slot=button]]:rounded-sm",
        className
      )}
      {...props}
    />
  )
}

type InputGroupCopyProps = {
  /** The text shown in the read-only field and put on the clipboard. */
  value: string
  /** Called once the clipboard took the value. */
  onCopy?: (value: string) => void
  /** Label of the button. */
  copyLabel?: string
  /** Label of the button for 1.5 s after a copy. */
  copiedLabel?: string
  /** Names the read-only field. */
  "aria-label"?: string
  className?: string
}

/**
 * A read-only field with a Copy button inside it: an invite link, an API key, a share URL. The button puts `value` on
 * the clipboard, turns into a check with "Copied" for 1.5 s and says so in a polite live region. "Copied" only
 * appears once the clipboard took the text (it is blocked in iframes, on http and when denied).
 */
function InputGroupCopy({
  value,
  onCopy,
  copyLabel = "Copy",
  copiedLabel = "Copied",
  "aria-label": ariaLabel = "Copy value",
  className,
}: InputGroupCopyProps) {
  const [copied, setCopied] = React.useState(false)
  const timer = React.useRef<number | undefined>(undefined)
  React.useEffect(() => () => window.clearTimeout(timer.current), [])
  const copy = () => {
    navigator.clipboard?.writeText(value).then(
      () => {
        setCopied(true)
        onCopy?.(value)
        window.clearTimeout(timer.current)
        timer.current = window.setTimeout(() => setCopied(false), 1500)
      },
      () => {}
    )
  }
  return (
    <InputGroup data-slot="input-group-copy" className={className}>
      <input readOnly value={value} aria-label={ariaLabel} className="min-w-0 truncate" />
      <InputGroupAddon>
        <Button type="button" variant="plain" size="sm" shape="rounded" onClick={copy}>
          {copied ? <Icon name="check" className="text-success" strokeWidth={1.5} /> : <Icon name="copy" strokeWidth={1.5} />}
          {copied ? copiedLabel : copyLabel}
        </Button>
        <span role="status" className="sr-only">{copied ? copiedLabel : ""}</span>
      </InputGroupAddon>
    </InputGroup>
  )
}

export { InputGroup, InputGroupAddon, InputGroupCopy }
export type { InputGroupCopyProps }

import * as React from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { Icon } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"

// --primary/--brand-primary is the indigo brand color; its text uses
// --primary-foreground/--brand-primary-foreground (white), which is AA-safe
// on indigo. gradient tracks the same primary token (light tint -> primary),
// so its text reuses primary-foreground too. outline keeps a fixed white
// background independent of the primary token, so its text stays a fixed
// dark color (#25272a) rather than tracking primary-foreground, which is
// white and would fail contrast on that fixed white background.
// See /scripts/contrast-audit.mjs.
//
// Hover and pressed on the filled variants are fixed token colours, the Figma values:
// primary and brand go brand-700 on hover and brand-800 pressed (white label 7.0:1 and
// 10.0:1), destructive goes red-800 and red-900 (6.5:1 and 10.6:1), the dark button
// goes dark-400 and dark-500. They replaced brightness-95, which dimmed fill and label
// together and left the pressed state with no colour at all (only a scale). The plain
// button follows the neutral-surface rule: hover bg-page, pressed bg-subtle.
// Focus (owner rule 31 Oct 2026): the border turns indigo and a 2 px indigo-300 outline sits directly on it
// (utility focus-ring); destructive keeps its red hue (focus-ring-error) and the dark button, whose border is
// its fill, gets a dark-300 ring. The gradient hover and pressed states are brand-600/700 and 700/800 stops.
//
// The gradient top stop was #6f74f5, which put the top edge of the button at
// 3.82:1 -- the gradient, not the token, was the failure. #5a5ef4 keeps a
// visible sheen (4.84:1 top, 4.99:1 bottom) and the inset white highlight
// carries the rest of the raised look. Its hover brightened (brightness-105,
// 3.52:1); it now darkens like the other filled variants (4.71:1 top).
const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center gap-2 border border-transparent text-sm font-medium whitespace-nowrap has-[>[data-slot=badge]:last-child]:pe-[calc((var(--btn-h)-2px-1.25rem)/2)] has-[>[data-slot=badge-counter]:last-child]:pe-[calc((var(--btn-h)-2px-1.25rem)/2)] transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:not-aria-[haspopup]:scale-[0.97] motion-reduce:active:scale-100 disabled:pointer-events-none disabled:opacity-40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-bg-page data-popup-open:bg-bg-page active:bg-bg-subtle focus-ring",
        primary:
          "border-primary bg-primary text-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        gradient:
          "border-primary bg-gradient-to-b from-[#5a5ef4] to-primary text-primary-foreground shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05),inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:from-(--brand-600) hover:to-(--brand-700) active:from-(--brand-700) active:to-(--brand-800) focus-ring",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-neutral-white active:bg-(--dark-500) active:text-neutral-white focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-0 focus-visible:outline-(color:--dark-300)",
        light: "bg-neutral-white bg-clip-padding text-primary hover:bg-(--light-200) focus-ring",
        // Figma Type=blue_outline: indigo rim, link-coloured label, indigo tint on hover.
        outline: "bg-card border-primary text-text-link hover:border-tint-text-indigo hover:bg-tint-indigo hover:text-tint-text-indigo active:bg-bg-subtle active:text-tint-text-indigo focus-ring",
        // Indigo tint: the selected-option look of the button group and segmented selectors.
        tint: "bg-tint-indigo text-tint-text-indigo focus-ring",
        // Figma Type=ghost / destructive / link (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-bg-page data-popup-open:bg-bg-page active:bg-bg-subtle focus-ring",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:border-(color:--red-800) hover:bg-(color:--red-800) active:border-(color:--red-900) active:bg-(color:--red-900) focus-ring-error",
        link: "bg-transparent px-0! text-text-link shadow-none underline-offset-4 hover:text-text-link-hover hover:underline active:text-text-link-pressed focus-ring",
      },
      shape: {
        rounded: "rounded-md",
        pill: "rounded-full",
      },
      size: {
        // Heights and paddings are density tokens (styles.css): compact 32/36/40/44/48,
        // data-density="comfortable" 36/40/44/48/56. The icon side sits 2 px tighter (2xl 4 px).
        sm: "h-(--control-sm) [--btn-h:var(--control-sm)] px-(--control-px-sm) text-sm has-data-[icon=inline-end]:pe-[calc(var(--control-px-sm)-0.125rem)] has-data-[icon=inline-start]:ps-[calc(var(--control-px-sm)-0.125rem)]",
        // Icon sizes follow the Figma Button sets: Small and Regular 16 px, Medium 20 px, Large and Xlarge 24 px. Heights and paddings are unchanged.
        md: "h-(--control-md) [--btn-h:var(--control-md)] px-(--control-px-md) text-sm has-data-[icon=inline-end]:pe-[calc(var(--control-px-md)-0.125rem)] has-data-[icon=inline-start]:ps-[calc(var(--control-px-md)-0.125rem)]",
        lg: "h-(--control-lg) [--btn-h:var(--control-lg)] px-(--control-px-lg) text-sm [&_svg:not([class*='size-'])]:size-5 has-data-[icon=inline-end]:pe-[calc(var(--control-px-lg)-0.125rem)] has-data-[icon=inline-start]:ps-[calc(var(--control-px-lg)-0.125rem)]",
        xl: "h-(--control-xl) [--btn-h:var(--control-xl)] px-(--control-px-xl) text-base [&_svg:not([class*='size-'])]:size-6 has-data-[icon=inline-end]:pe-[calc(var(--control-px-xl)-0.125rem)] has-data-[icon=inline-start]:ps-[calc(var(--control-px-xl)-0.125rem)]",
        "2xl": "h-(--control-2xl) [--btn-h:var(--control-2xl)] px-(--control-px-2xl) text-lg [&_svg:not([class*='size-'])]:size-6 has-data-[icon=inline-end]:pe-[calc(var(--control-px-2xl)-0.25rem)] has-data-[icon=inline-start]:ps-[calc(var(--control-px-2xl)-0.25rem)]",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

type ButtonPhase = "idle" | "pending" | "success" | "error"

function Button({
  className,
  variant,
  shape,
  size,
  children,
  onClick,
  pending,
  phase,
  ...props
}: ButtonPrimitive.Props &
  VariantProps<typeof buttonVariants> & {
    /**
     * Shows a spinner in place of the leading icon and ignores presses.
     * The button stays focusable and keeps its colour (it is not disabled).
     */
    pending?: boolean
    /**
     * Async feedback: pending shows a spinner, success a check, error a retry
     * icon. The label is yours (for example Saving…, Saved, Retry). Keep the
     * width constant with a fixed width on the button so it does not jump
     * between phases.
     */
    phase?: ButtonPhase
  }) {
  const status: ButtonPhase = phase ?? (pending ? "pending" : "idle")
  const isIdle = status === "idle"

  const resolvedVariant = variant ?? "primary"
  const effectiveVariant =
    status === "error" &&
    ["primary", "brand", "gradient"].includes(resolvedVariant)
      ? "destructive"
      : variant

  const filteredChildren = React.Children.toArray(children).filter((child) => {
    if (!React.isValidElement<{ "data-icon"?: string }>(child)) {
      return true
    }
    return child.props["data-icon"] !== "inline-start"
  })

  const quiet = ["plain", "ghost", "outline", "tint"].includes(resolvedVariant)

  let statusIcon: React.ReactNode = null
  if (status === "pending") {
    statusIcon = (
      <Icon
        name="spinner"
        aria-hidden
        data-icon="inline-start"
        className="animate-spin motion-reduce:animate-none"
      />
    )
  } else if (status === "success") {
    statusIcon = (
      <Icon
        name="check"
        aria-hidden
        data-icon="inline-start"
        strokeWidth={2}
        className={quiet ? "text-text-success" : undefined}
      />
    )
  } else if (status === "error") {
    statusIcon = (
      <Icon
        name="retry"
        aria-hidden
        data-icon="inline-start"
        strokeWidth={2}
        className={quiet ? "text-text-error" : undefined}
      />
    )
  }

  const handleClick: NonNullable<ButtonPrimitive.Props["onClick"]> = (event) => {
    if (status === "pending") {
      event.preventDefault()
      return
    }
    onClick?.(event)
  }

  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(
        buttonVariants({ variant: isIdle ? variant : effectiveVariant, shape, size, className })
      )}
      data-phase={isIdle ? undefined : status}
      aria-busy={isIdle ? undefined : status === "pending" ? true : undefined}
      data-pending={isIdle ? undefined : status === "pending" ? "" : undefined}
      onClick={isIdle ? onClick : handleClick}
      {...props}
    >
      {isIdle ? null : statusIcon}
      {isIdle ? children : filteredChildren}
    </ButtonPrimitive>
  )
}

export { Button, buttonVariants }
export type { ButtonPhase }
